function weekendPanel(){const count=state.recipes.filter(r=>r.category==='noodle').length;return `<section class="weekend-panel"><div class="weekend-symbol">🍜</div><div class="weekend-copy"><div class="eyebrow">CUỐI TUẦN ĐỔI VỊ</div><h2>Một tô nóng, cả nhà cùng vui.</h2><p>${count} món nước dễ chọn · Phở, bún, mì, hủ tiếu, cháo & súp · 15–30 phút với nguyên liệu chuẩn bị sẵn.</p><span class="pill">${state.preferences.weekendSoup?'✓ Tự ưu tiên món nước '+({lunch:'bữa trưa',dinner:'bữa tối',both:'trưa & tối'}[state.preferences.weekendMeals]||'bữa trưa')+' cuối tuần':'Có thể chọn riêng cho từng bữa'}</span></div><div class="toolbar"><button class="btn primary" data-action="weekend-picker">Chọn món cuối tuần ↗</button><button class="text-btn" data-action="browse-soups">Xem cả ${count} món</button></div></section>`}
function weekendPicker(){const sat=addDays(weekStart,5),sun=addDays(weekStart,6);modal('Cuối tuần, ăn món nước nhé?',`<p class="hint">Chọn ngày, bữa ăn và món. Một món nước thay cả bữa, không tự cộng cơm trắng hay canh phụ. Các bữa đã khóa cần mở khóa trước.</p><div class="form-grid"><div class="field"><label for="soup-date">Ngày ăn</label><select id="soup-date"><option value="${sat}">Thứ Bảy · ${dateLabel(sat)}</option><option value="${sun}">Chủ Nhật · ${dateLabel(sun)}</option></select></div><div class="field"><label for="soup-type">Bữa ăn</label><select id="soup-type">${state.preferences.lunch?'<option value="lunch">Bữa trưa</option>':''}<option value="dinner">Bữa tối</option></select></div></div><div class="recipe-tools"><div class="searchbox"><span>⌕</span><input id="soup-search" placeholder="Tìm bún, phở, cháo, gà, tôm…" aria-label="Tìm món nước"></div><select class="input" id="soup-time" style="width:auto" aria-label="Thời gian món nước"><option value="30">Tối đa 30 phút</option><option value="20">Tối đa 20 phút</option><option value="15">Tối đa 15 phút</option></select></div><div class="callout">Thời gian đã ghi rõ điều kiện: nước dùng có sẵn, gà chín hoặc cơm chín. Không bao gồm thời gian hầm nước dùng hay rã đông. Súp bắp và súp rong biển là bữa nhẹ; có thể cần tăng khẩu phần hoặc thêm món khác.</div><div id="soup-results" class="soup-picker">${soupItems('',30)}</div>`,`<button class="btn" data-action="browse-soups">Mở kho món nước</button><button class="btn primary" data-action="close-modal">Xong</button>`,true)}
function soupItems(query,maxTime){const q=query.toLocaleLowerCase('vi');const rows=state.recipes.filter(r=>r.category==='noodle'&&r.time<=maxTime&&(!q||r.name.toLocaleLowerCase('vi').includes(q)||r.ingredients.some(i=>INGREDIENTS[i.id][0].toLocaleLowerCase('vi').includes(q))));return rows.map(r=>`<article class="soup-option"><div class="soup-art">${foodArt(r)}</div><div><h3>${esc(r.name)}</h3><span class="pill ${r.time<=20?'':'orange'}">◷ ${r.time} phút</span><small> · ${aud(recipeCost(r))} / 4 người</small><p>${(r.tags||[]).slice(1).map(esc).join(' · ')||esc(r.prep)}</p></div><button class="btn small ${allowedRecipe(r,state)?'soft':''}" data-action="weekend-apply" data-id="${r.id}" ${!allowedRecipe(r,state)?'disabled':''}>${allowedRecipe(r,state)?'Chọn món':'Cần tránh'}</button></article>`).join('')||'<div class="empty">Chưa có món phù hợp. Thử đổi từ khóa hoặc thời gian.</div>'}
function applyWeekendSoup(id){const date=$('#soup-date').value,type=$('#soup-type').value,m=currentWeek().days[date][type],r=state.recipes.find(r=>r.id===id);if(!r||!allowedRecipe(r,state))return;if(m.cooked||m.locked){toast('Bữa này đã nấu hoặc đang khóa. Hãy mở khóa / hoàn tác trước.',true);return}m.recipes=[clone(r)];m.tasks={};log(`Chọn món nước ${r.name} cho ${type==='lunch'?'trưa':'tối'} ${dateLabel(date)}`);save(`Đã chọn ${r.name} cho ${dayName(date)} ${type==='lunch'?'trưa':'tối'}.`);render();}
document.addEventListener('input',e=>{if(e.target.id==='soup-search'&&$('#soup-results'))$('#soup-results').innerHTML=soupItems(e.target.value,+$('#soup-time').value)});
document.addEventListener('change',e=>{if(e.target.id==='soup-time'&&$('#soup-results'))$('#soup-results').innerHTML=soupItems($('#soup-search').value,+e.target.value)});
// Wheel picker keeps purchase quantities separate from recipe requirements.
let purchasePicker=null,purchaseScrollTimer=null;
function openPurchasePicker(id){
 const [start,end]=shopDates(),row=shopping(state,currentWeek(),start,end).find(r=>r.id===id);if(!row)return;
 const unit=INGREDIENTS[id][1],step=unit==='quả'?1:50;
 purchasePicker={id,start,end,row,qty:row.qty,step,unit,displayUnit:(unit==='g'&&row.qty>=1000)?'kg':(unit==='ml'&&row.qty>=1000)?'l':unit,values:[],index:0};
 modal('Chọn lượng mua',`<div class="purchase-item-heading"><span>${INGREDIENTS[id][4]}</span><div><h3>${esc(INGREDIENTS[id][0])}</h3><p>Áp dụng ${dateLabel(start)} – ${dateLabel(end)} · ${shopRange==='week'?'Cả tuần':shopRange==='today'?'Ngày đang chọn':'3 ngày đang chọn'}</p></div></div><div class="purchase-requirement"><div><small>CẦN MUA THEO THỰC ĐƠN</small><b>${fmtQty(row.missing,unit)}</b></div><div><small>GỢI Ý ${state.preferences.packed?'THEO GÓI':'TỰ ĐỘNG'}</small><b>${fmtQty(row.suggested,unit)}</b></div></div><p class="wheel-instruction">Vuốt lên / xuống hoặc cuộn để chọn lượng muốn mua.</p><div class="weight-wheel-shell"><span class="wheel-selection" aria-hidden="true"></span><div id="purchase-wheel" class="weight-wheel" role="listbox" tabindex="0" aria-label="Cuộn chọn lượng mua" aria-describedby="wheel-keyboard-help"></div></div><small id="wheel-keyboard-help" class="wheel-help">Có thể bấm vào số hoặc dùng phím ↑ ↓.</small><div class="weight-quick-picks">${(unit==='quả'?[2,4,6,12]:[250,500,1000,2000]).map(q=>`<button class="btn small" data-action="weight-quick" data-qty="${q}">${fmtQty(q,unit)}</button>`).join('')}</div><div class="purchase-manual-grid"><div class="field"><label for="weight-exact">Hoặc nhập số lượng</label><input id="weight-exact" type="number" inputmode="decimal" min="0" max="${purchasePicker.displayUnit==='kg'||purchasePicker.displayUnit==='l'?1000:1000000}" step="${unit==='quả'?'1':'any'}"></div><div class="field"><label for="weight-unit">Đơn vị</label><select id="weight-unit">${(unit==='g'?['g','kg']:unit==='ml'?['ml','l']:[unit]).map(u=>`<option value="${u}" ${u===purchasePicker.displayUnit?'selected':''}>${u==='l'?'lít':u}</option>`).join('')}</select></div><div class="field"><label for="weight-step">Bước cuộn</label><select id="weight-step">${(unit==='quả'?[1,2,6]:[10,50,100,250,500]).map(n=>`<option value="${n}" ${n===step?'selected':''}>${fmtQty(n,unit)}</option>`).join('')}</select></div></div><div class="purchase-chosen"><div><small>LƯỢNG BẠN CHỌN</small><b id="purchase-chosen-qty"></b></div><div><small>DỰ KIẾN CHI PHÍ</small><b id="purchase-chosen-cost"></b></div></div><div id="purchase-shortage" class="callout" role="status" aria-live="polite"></div><p class="hint">Giữ nguyên công thức. Đổi lượng mua sẽ bỏ dấu “đã mua” để bạn kiểm tra lại.</p>`,`<button class="btn" data-action="reset-purchase-quantity">Dùng lượng tự động</button><button class="btn primary" data-action="save-purchase-quantity">Lưu lượng mua</button>`);
 $('.modal').classList.add('purchase-modal');renderPurchaseWheel();updatePurchaseSummary();
 const wheel=$('#purchase-wheel');wheel.addEventListener('scroll',()=>{clearTimeout(purchaseScrollTimer);purchaseScrollTimer=setTimeout(()=>{if(!purchasePicker||!$('#purchase-wheel'))return;selectPurchaseWheel(Math.round(wheel.scrollTop/44),false)},90)},{passive:true});
 wheel.addEventListener('keydown',e=>{if(!purchasePicker)return;let index=purchasePicker.index;if(e.key==='ArrowDown')index++;else if(e.key==='ArrowUp')index--;else if(e.key==='Home')index=0;else if(e.key==='End')index=purchasePicker.values.length-1;else return;e.preventDefault();selectPurchaseWheel(index,true)});
}
function renderPurchaseWheel(){
 if(!purchasePicker||!$('#purchase-wheel'))return;const p=purchasePicker;
 const max=Math.min(1000000,Math.max(!['g','ml'].includes(p.unit)?60:10000,Math.ceil(Math.max(p.qty,p.row.suggested)/p.step)*p.step+p.step*10));
 // Keep extreme imported amounts bounded without losing the exact choice.
 const count=Math.floor(max/p.step);let values=[];
 if(count<=1200){for(let n=0;n<=count;n++)values.push(n*p.step)}else{const center=Math.round(p.qty/p.step);for(let n=Math.max(0,center-500);n<=Math.min(count,center+500);n++)values.push(n*p.step);values.push(0,max)}
 values.push(p.qty,p.row.suggested);p.values=[...new Set(values.map(n=>Math.round(n*10)/10).filter(n=>n>=0&&n<=1e6))].sort((a,b)=>a-b);p.index=p.values.indexOf(p.qty);
 $('#purchase-wheel').innerHTML=p.values.map((q,index)=>`<div class="weight-option ${index===p.index?'selected':''}" id="purchase-option-${index}" role="option" aria-selected="${index===p.index}" data-action="wheel-select" data-index="${index}">${fmtQty(q,p.unit)}</div>`).join('');
 $('#purchase-wheel').setAttribute('aria-activedescendant','purchase-option-'+p.index);$('#purchase-wheel').scrollTop=p.index*44;
}
function selectPurchaseWheel(index,scroll){if(!purchasePicker)return;const p=purchasePicker;p.index=Math.max(0,Math.min(p.values.length-1,index));p.qty=p.values[p.index];$$('.weight-option',$('#purchase-wheel')).forEach((el,i)=>{el.classList.toggle('selected',i===p.index);el.setAttribute('aria-selected',i===p.index?'true':'false')});$('#purchase-wheel').setAttribute('aria-activedescendant','purchase-option-'+p.index);if(scroll)$('#purchase-wheel').scrollTop=p.index*44;updatePurchaseSummary()}
function setPickerQuantity(qty){if(!purchasePicker||!Number.isFinite(qty)||qty<0||qty>1e6||(purchasePicker.unit==='quả'&&!Number.isInteger(qty)))return false;purchasePicker.qty=Math.round(qty*10)/10;renderPurchaseWheel();updatePurchaseSummary();return true}
function updatePurchaseSummary(updateInput=true){if(!purchasePicker||!$('#purchase-chosen-qty'))return;const p=purchasePicker,multiplier=['kg','l'].includes(p.displayUnit)?1000:1;$('#purchase-chosen-qty').textContent=fmtQty(p.qty,p.unit);$('#purchase-chosen-cost').textContent=aud(p.qty*INGREDIENTS[p.id][3]);if(updateInput)$('#weight-exact').value=+(p.qty/multiplier).toFixed(4);const short=Math.max(0,p.row.missing-p.qty);$('#purchase-shortage').textContent=short>.01?`Bạn chọn ít hơn ${fmtQty(short,p.unit)} so với lượng cần mua theo thực đơn.`:p.qty>p.row.missing?`Mua dư ${fmtQty(p.qty-p.row.missing,p.unit)} so với lượng cần; có thể để dành cho bữa khác.`:'Vừa đủ lượng cần mua theo thực đơn.';}
function savePurchasePicker(){if(!purchasePicker)return;const input=$('#weight-exact');if(!input.reportValidity())return;const p=purchasePicker,multiplier=['kg','l'].includes(p.displayUnit)?1000:1;const value=+input.value*multiplier;if(input.value===''||!Number.isFinite(value)||value<0||value>1e6||(p.unit==='quả'&&!Number.isInteger(value))){toast('Nhập lượng hợp lệ; trứng và chanh cần số nguyên.',true);return}setPurchaseQuantity(currentWeek(),p.start,p.end,p.id,value);log(`Chọn mua ${fmtQty(value,p.unit)} ${INGREDIENTS[p.id][0]}`);save('Đã cập nhật lượng mua và ngân sách.');purchasePicker=null;clearTimeout(purchaseScrollTimer);closeModal();render()}
function resetPurchasePicker(){if(!purchasePicker)return;const p=purchasePicker;resetPurchaseQuantity(currentWeek(),p.start,p.end,p.id);delete currentWeek().bought[p.id];save('Đã trở về lượng mua tự động.');purchasePicker=null;clearTimeout(purchaseScrollTimer);closeModal();render()}
document.addEventListener('input',e=>{if(e.target.id!=='weight-exact'||!purchasePicker)return;const value=e.target.valueAsNumber*(['kg','l'].includes(purchasePicker.displayUnit)?1000:1);if(!Number.isFinite(value)||value<0||value>1e6)return;purchasePicker.qty=value;updatePurchaseSummary(false)});
document.addEventListener('change',e=>{if(!purchasePicker)return;if(e.target.id==='weight-unit'){purchasePicker.displayUnit=e.target.value;$('#weight-exact').max=['kg','l'].includes(e.target.value)?1000:1000000;updatePurchaseSummary()}if(e.target.id==='weight-step'){purchasePicker.step=+e.target.value;renderPurchaseWheel();updatePurchaseSummary()}if(e.target.id==='weight-exact'){const value=e.target.valueAsNumber*(['kg','l'].includes(purchasePicker.displayUnit)?1000:1);if(Number.isFinite(value)&&value>=0&&value<=1e6)setPickerQuantity(value)}});
